declare(strict_types=1);require __DIR__.'/_auth.php';$auth->requireRole('ADMIN');$users=$auth->users()->all();$title='Users';$activePage='users';require __DIR__.'/partials/header.php';?>
<section class="panel"><div class="panel-head"><div><h2>Internal users</h2><p>Accounts and role assignments.</p></div><a class="btn primary" href="user_edit.php">+ Create User</a></div><div class="table-wrap"><table><thead><tr><th>Username</th><th>Full Name</th><th>Roles</th><th>Status</th><th>Last Login</th><th>Actions</th></tr></thead><tbody><?php foreach($users as $u):?><tr><td><strong><?=e($u['username'])?></strong></td><td><?=e($u['full_name'])?></td><td><div class="chip-list"><?php foreach($u['roles'] as $role):?><span class="badge operator-chip"><?=e(str_replace('_',' ',$role))?></span><?php endforeach;?></div></td><td><span class="badge <?=$u['active']?'on':'off'?>"><?=$u['active']?'Active':'Inactive'?></span></td><td><?=e($u['last_login_at']??'Never')?></td><td><div class="actions"><a href="user_edit.php?id=<?=(int)$u['id']?>">Edit</a><form method="post" action="user_toggle.php"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="id" value="<?=(int)$u['id']?>"><input type="hidden" name="active" value="<?=$u['active']?0:1?>"><button><?=$u['active']?'Deactivate':'Activate'?></button></form><a href="user_password_reset.php?id=<?=(int)$u['id']?>">Reset Password</a></div></td></tr><?php endforeach;?></tbody></table></div></section><?php require __DIR__.'/partials/footer.php';?>
